CREATE TABLE job_postings_s310(id TEXT PRIMARY KEY,requisition_id TEXT NOT NULL REFERENCES requisitions(id),title TEXT NOT NULL,job_description TEXT NOT NULL DEFAULT '',candidate_requirements TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN ('DRAFT','PENDING_APPROVAL','APPROVED','REJECTED','PUBLISHED','PAUSED','UNPUBLISHED')),published_at TEXT,created_at TEXT NOT NULL DEFAULT (datetime('now')),updated_at TEXT NOT NULL DEFAULT (datetime('now')),work_location_id TEXT REFERENCES recruitment_catalog_items(id),work_mode_id TEXT REFERENCES recruitment_catalog_items(id),application_deadline TEXT,show_salary INTEGER NOT NULL DEFAULT 0 CHECK(show_salary IN (0,1)),salary_min REAL,salary_max REAL,source_submission_id TEXT REFERENCES requisition_approval_submissions(id),source_content_hash TEXT,version INTEGER NOT NULL DEFAULT 0 CHECK(version>=0),created_by TEXT,updated_by TEXT,content_version INTEGER NOT NULL DEFAULT 0,approved_content_version INTEGER,approved_content_hash TEXT,approved_by TEXT,approved_at TEXT,published_by TEXT);
INSERT INTO job_postings_s310(id,requisition_id,title,job_description,candidate_requirements,status,published_at,created_at,updated_at,work_location_id,work_mode_id,application_deadline,show_salary,salary_min,salary_max,source_submission_id,source_content_hash,version,created_by,updated_by) SELECT id,requisition_id,title,job_description,candidate_requirements,status,published_at,created_at,updated_at,work_location_id,work_mode_id,application_deadline,show_salary,salary_min,salary_max,source_submission_id,source_content_hash,version,created_by,updated_by FROM job_postings;
DROP TABLE job_postings;
ALTER TABLE job_postings_s310 RENAME TO job_postings;
CREATE INDEX job_postings_requisition ON job_postings(requisition_id,status);
CREATE INDEX job_postings_public ON job_postings(status,published_at,id);
CREATE INDEX job_posting_draft_source ON job_postings(requisition_id,status,id);
CREATE TABLE job_posting_content_versions(posting_id TEXT NOT NULL REFERENCES job_postings(id),content_version INTEGER NOT NULL CHECK(content_version>0),document_json TEXT NOT NULL,document_hash TEXT NOT NULL,content_hash TEXT NOT NULL,source_hash TEXT NOT NULL,source_submission_id TEXT NOT NULL REFERENCES requisition_approval_submissions(id),actor_id TEXT NOT NULL,actor_name TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (datetime('now')),PRIMARY KEY(posting_id,content_version));
CREATE TABLE job_posting_publication_events(id TEXT PRIMARY KEY,posting_id TEXT NOT NULL REFERENCES job_postings(id),event_version INTEGER NOT NULL,content_version INTEGER NOT NULL,action TEXT NOT NULL,before_status TEXT NOT NULL,after_status TEXT NOT NULL,actor_id TEXT NOT NULL,actor_name TEXT NOT NULL,reason TEXT,request_id TEXT,fingerprint TEXT,response_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (datetime('now')),UNIQUE(posting_id,event_version),UNIQUE(actor_id,request_id));
CREATE INDEX job_publication_events_posting ON job_posting_publication_events(posting_id,event_version);
CREATE TRIGGER job_posting_content_versions_no_update BEFORE UPDATE ON job_posting_content_versions BEGIN SELECT RAISE(ABORT,'JOB_PUBLICATION_HISTORY_IMMUTABLE');END;
CREATE TRIGGER job_posting_content_versions_no_delete BEFORE DELETE ON job_posting_content_versions BEGIN SELECT RAISE(ABORT,'JOB_PUBLICATION_HISTORY_IMMUTABLE');END;
CREATE TRIGGER job_posting_publication_events_no_update BEFORE UPDATE ON job_posting_publication_events BEGIN SELECT RAISE(ABORT,'JOB_PUBLICATION_HISTORY_IMMUTABLE');END;
CREATE TRIGGER job_posting_publication_events_no_delete BEFORE DELETE ON job_posting_publication_events BEGIN SELECT RAISE(ABORT,'JOB_PUBLICATION_HISTORY_IMMUTABLE');END;
